let slideIndexes = {
  slideshow1: 1,
  slideshow2: 1
};

function plusSlides(n, slideshowId) {
  showSlides(slideIndexes[slideshowId] += n, slideshowId);
}

function currentSlide(n, slideshowId) {
  showSlides(slideIndexes[slideshowId] = n, slideshowId);
}

function showSlides(n, slideshowId) {
  let i;
  let slides = document.getElementById(slideshowId).getElementsByClassName("mySlides");
  let dots = document.getElementById(slideshowId).getElementsByClassName("dot");

  // If no slides or dots exist, return early
  if (!slides || slides.length === 0 || !dots || dots.length === 0) return;

  // Adjust the slide index to loop
  if (n > slides.length) { slideIndexes[slideshowId] = 1; }
  if (n < 1) { slideIndexes[slideshowId] = slides.length; }

  // Hide all slides
  for (i = 0; i < slides.length; i++) {
    slides[i].style.display = "none";  
  }

  // Remove the "active" class from all dots
  for (i = 0; i < dots.length; i++) {
    dots[i].className = dots[i].className.replace(" active", "");
  }

  // Show the current slide and add the "active" class to the corresponding dot
  slides[slideIndexes[slideshowId] - 1].style.display = "block";  
  dots[slideIndexes[slideshowId] - 1].className += " active";
}

// Ensure slideshows are initialized after the page has fully loaded
document.addEventListener("DOMContentLoaded", function() {
  showSlides(slideIndexes.slideshow1, 'slideshow1');
  showSlides(slideIndexes.slideshow2, 'slideshow2');
});
